}

protocol ListDelegate: AnyObject {
    func didSelect(_ index: Int)
}
final class ListView {
    weak var delegate: ListDelegate?
}

final class ViewModel {
    var onChange: (() -> Void)?
    func bind() {
        onChange = { [weak self] in self?.reload() }
    }
    func reload() {}
}

